fn legmulx(c: Vec<f32>) -> Vec<f32> {
    // The output will have one more coefficient than the input.
    // result[0] = 0.0, and for each j in 0..c.len(), result[j+1] = c[j].
    let mut result = Vec::with_capacity(c.len() + 1);
    
    // First coefficient of x·p(x) is always 0.0
    result.push(0.0);
    
    // Shift all the input coefficients one slot to the right
    for coeff in c.into_iter() {
        result.push(coeff);
    }
    
    result
}

